/** Return a fresh presentation object, safe for the UI to decorate locally. */
export function getPlayScene(mission, session = {}) {
  const chapter = chapters[Number(mission?.chapter)] || chapters[1];
  const encounter = encounters[mission?.id];
  const first = firstSteps[mission?.id] || {};
  const stepIndex = mission?.steps?.findIndex((_, index) => !session.done?.[index]) ?? -1;
  const current = stepIndex >= 0 ? mission.steps[stepIndex] : null;
  const currentCopy = current ? first[current.id] : null;
  const intro = encounter
    ? [line(encounter[2], encounter[3]), line(encounter[4], encounter[5])]
    : chapter.intro;
  return {
    title: encounter?.[0] || mission?.title || chapter.title,
    goal: currentCopy?.goal || encounter?.[1] || chapter.goal,
    intro: intro.map(item => ({ ...item })),
    win: encounter?.[6] || chapter.win,
    wrong: currentCopy?.wrong ? [currentCopy.wrong, ...chapter.wrong] : [...chapter.wrong],
    propLabels: { ...chapter.propLabels },
    banter: [...chapter.banter],
    boss: mission?.phase === 'boss' ? { ...chapter.boss, phases: [...chapter.boss.phases] } : null,
    steps: Object.fromEntries(Object.entries(first).map(([id, value]) => [id, { ...value }])),
    current: currentCopy ? { stepId: current.id, ...currentCopy } : null,
  };
}

export const playChapterCount = Object.keys(chapters).length;
export const playEncounterCount = Object.keys(encounters).length;
